kit.scene('tears', {
  init(kit) {
    this.s = W.shot(kit, {
      id: 'tears', tears: true,
      cast: [{ who: 'mandodari', x: 370, y: 1990, s: 1.7, flip: true }],
      cam: [1.0, 1.05, 470, 500, 480, 480],
      arm: (t) => 8 + 5 * Math.sin(t * 1.3),
      lines: [[24.9, 26.3, 'कैसे बचाएगा?', 0, 0], [26.9, 29.28, 'देव, दानव, गंधर्व — कोई नहीं बचा पाएगा।', 0, 0]],
    });
  },
  render(t) { this.s.render(t); },
});
